// ---------------------------------------------------------------------------
// The app icons. One description, drawn by scripts/build-icons.mjs (every file
// under brand/), Studio's About page (BrandArt.tsx) and Pocket's (PocketMark.tsx),
// so they cannot drift apart. Every shape is a plain path (no clip paths), in a
// 100 x 100 box, painted in order.
//
//   NH Studio: a planet rising behind a gently curved horizon, lit from the
//              upper left (its lower right in shade), a soft atmosphere halo,
//              and Charon in the sky.
//   NH Pocket: a close-up of a large planet in the lower-right corner, cut by
//              the icon's edge; only its upper-left crescent is lit. Charon
//              beyond it.
// ---------------------------------------------------------------------------

export type BrandApp = 'studio' | 'pocket';

export interface BrandShape {
  d: string;
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
  opacity?: number;
  /** 'body' shapes are the rising planet the About pages animate. */
  layer: 'sky' | 'body' | 'scene';
}

export interface BrandIconOptions {
  /** 32 px and below: thicker strokes, no halo and no Charon. */
  small?: boolean;
  /** Android adaptive layers: 'background' is the sky alone, 'foreground' the rest. */
  parts?: 'all' | 'background' | 'foreground';
  /** Monochrome (Android themed icons): the foreground's silhouette in this colour. */
  mono?: string | null;
}

export const BRAND_COLORS = {
  studio: { sky: '#0b111c', planet: '#5fd4a3', shade: '#3a9e78', ground: '#103a30', band: '#1f6b54', line: '#f2fbf6', halo: '#5fd4a3', moon: '#2f7a62' },
  pocket: { sky: '#1f6b54', planet: '#f2fbf6', shade: '#bfe2d2', ground: '#081a16', halo: '#f2fbf6', moon: '#78c4a3', moonShade: '#4f9f80' },
} as const;

/**
 * About-page animation: where the rising planet ('body' shapes) starts, as an
 * offset it slides back from. Studio's climbs along its horizon from the lower
 * left; Pocket's slides in from its corner.
 */
export const BRAND_ICON = {
  durationMs: 1600,
  studio: { rise: { dx: -16, dy: 34 } },
  pocket: { rise: { dx: 22, dy: 22 } },
} as const;

type Pt = [number, number];
interface Circle { c: Pt; r: number }
const n2 = (v: number) => Math.round(v * 100) / 100;
const pt = ([x, y]: Pt) => `${n2(x)},${n2(y)}`;

function circlePath({ c: [x, y], r }: Circle): string {
  return `M${n2(x - r)},${n2(y)} A${n2(r)},${n2(r)} 0 1 0 ${n2(x + r)},${n2(y)} A${n2(r)},${n2(r)} 0 1 0 ${n2(x - r)},${n2(y)} Z`;
}

/** The two crossing points of equal circles a and b (a's view: p1 then p2 counter-clockwise). */
function crossings(a: Circle, b: Circle): [Pt, Pt] {
  const [ax, ay] = a.c, [bx, by] = b.c;
  const dx = bx - ax, dy = by - ay, d = Math.hypot(dx, dy);
  const h = Math.sqrt(Math.max(0, a.r * a.r - (d / 2) * (d / 2)));
  const mx = ax + dx / 2, my = ay + dy / 2, ux = -dy / d, uy = dx / d;
  return [[mx + ux * h, my + uy * h], [mx - ux * h, my - uy * h]];
}

/** SVG arc on circle k from p to q passing through `via`. */
function arcVia(k: Circle, p: Pt, q: Pt, via: Pt): string {
  const ang = (v: Pt) => Math.atan2(v[1] - k.c[1], v[0] - k.c[0]);
  const norm = (t: number) => ((t % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
  const sweepCw = norm(ang(via) - ang(p)) < norm(ang(q) - ang(p)); // increasing screen angle = clockwise
  const span = sweepCw ? norm(ang(q) - ang(p)) : norm(ang(p) - ang(q));
  return `A${n2(k.r)},${n2(k.r)} 0 ${span > Math.PI ? 1 : 0} ${sweepCw ? 1 : 0} ${pt(q)}`;
}

const toward = (k: Circle, other: Pt, sign: 1 | -1): Pt => {
  const dx = other[0] - k.c[0], dy = other[1] - k.c[1], d = Math.hypot(dx, dy);
  return [k.c[0] + (sign * k.r * dx) / d, k.c[1] + (sign * k.r * dy) / d];
};

/** a ∩ b for equal circles: a lens. */
function lens(a: Circle, b: Circle): string {
  const [p1, p2] = crossings(a, b);
  return `M${pt(p1)} ${arcVia(a, p1, p2, toward(a, b.c, 1))} ${arcVia(b, p2, p1, toward(b, a.c, 1))} Z`;
}

/** a minus b for equal circles: a crescent. */
function crescent(a: Circle, b: Circle): string {
  const [p1, p2] = crossings(a, b);
  return `M${pt(p1)} ${arcVia(a, p1, p2, toward(a, b.c, -1))} ${arcVia(b, p2, p1, toward(b, a.c, 1))} Z`;
}

/** A body lit from the upper left: [shade disc, lit lens]. */
function litBody(k: Circle, light: string, dark: string, layer: BrandShape['layer']): BrandShape[] {
  const lit: Circle = { c: [k.c[0] - k.r * 0.42, k.c[1] - k.r * 0.22], r: k.r };
  return [{ d: circlePath(k), fill: dark, layer }, { d: lens(k, lit), fill: light, layer }];
}

// Studio's horizon: the old diagonal (-5,75) -> (105,44), bowed up by 5 at the middle.
const hzY = (x: number) => 75 + ((44 - 75) / 110) * (x + 5) - 5 * (1 - ((x - 50) / 70) ** 2);
function hzPoints(offset: number): Pt[] {
  const pts: Pt[] = [];
  for (let x = -20; x <= 120; x += 4) pts.push([x, hzY(x) + offset]);
  return pts;
}
const poly = (pts: Pt[]) => pts.map((p, i) => `${i ? 'L' : 'M'}${pt(p)}`).join(' ');

function studioShapes(small: boolean): BrandShape[] {
  const c = BRAND_COLORS.studio;
  const planet: Circle = { c: [58, 47], r: small ? 18 : 16 };
  const band = small ? 16 : 14;
  const top = hzPoints(0);
  const out: BrandShape[] = [{ d: 'M-30,-30 H130 V130 H-30 Z', fill: c.sky, layer: 'sky' }];
  if (!small) out.push({ d: circlePath({ c: [27, 27], r: 5.2 }), fill: c.moon, layer: 'scene' });
  if (!small) out.push({ d: circlePath({ c: planet.c, r: planet.r + 3.6 }), fill: c.halo, opacity: 0.18, layer: 'body' });
  out.push(...litBody(planet, c.planet, c.shade, 'body'));
  out.push({ d: `${poly(top)} L120,120 L-20,120 Z`, fill: c.ground, layer: 'scene' });
  out.push({ d: `${poly(top)} ${poly(hzPoints(band).reverse()).replace('M', 'L')} Z`, fill: c.band, layer: 'scene' });
  out.push({ d: poly(top), stroke: c.line, strokeWidth: small ? 7.5 : 5, layer: 'scene' });
  return out;
}

const POCKET_PLANET: Circle = { c: [74, 74], r: 36 };
const pocketShadeAt = (s: number): Circle => ({ c: [74 + 36 * s * 0.8, 74 + 36 * s * 0.55], r: 36 });

function pocketShapes(small: boolean): BrandShape[] {
  const c = BRAND_COLORS.pocket;
  const A = POCKET_PLANET;
  const out: BrandShape[] = [{ d: 'M-30,-30 H130 V130 H-30 Z', fill: c.sky, layer: 'sky' }];
  if (!small) out.push(...litBody({ c: [28, 28], r: 6 }, c.moon, c.moonShade, 'scene'));
  if (!small) out.push({ d: circlePath({ c: A.c, r: A.r + 3.6 }), fill: c.halo, opacity: 0.16, layer: 'body' });
  out.push({ d: circlePath(A), fill: c.planet, layer: 'body' });
  out.push({ d: lens(A, pocketShadeAt(0.32)), fill: c.shade, layer: 'body' });
  out.push({ d: lens(A, pocketShadeAt(0.6)), fill: c.ground, layer: 'body' });
  return out;
}

function monoShapes(app: BrandApp, small: boolean, colour: string): BrandShape[] {
  if (app === 'pocket') {
    const out: BrandShape[] = [];
    if (!small) out.push({ d: circlePath({ c: [28, 28], r: 6 }), fill: colour, layer: 'scene' });
    out.push({ d: crescent(POCKET_PLANET, pocketShadeAt(0.6)), fill: colour, layer: 'body' });
    return out;
  }
  const planet: Circle = { c: [58, 47], r: small ? 18 : 16 };
  return [
    { d: circlePath(planet), fill: colour, layer: 'body' },
    { d: poly(hzPoints(0)), stroke: colour, strokeWidth: small ? 7.5 : 5, layer: 'scene' },
  ];
}

/** The icon's shapes, painted in order. */
export function brandIconShapes(app: BrandApp, { small = false, parts = 'all', mono = null }: BrandIconOptions = {}): BrandShape[] {
  if (mono) return monoShapes(app, small, mono);
  const shapes = app === 'studio' ? studioShapes(small) : pocketShapes(small);
  if (parts === 'background') return shapes.filter((s) => s.layer === 'sky');
  if (parts === 'foreground') return shapes.filter((s) => s.layer !== 'sky');
  return shapes;
}
